/* rpn/lexer.h - the module rpn::lexer, ported to C (CodeCoreMorph, D-75). */
#ifndef RPN_LEXER_H
#define RPN_LEXER_H

#include <stddef.h>

/* An arithmetic operator (Rust's enum Op). */
typedef enum rpn_op {
    RPN_OP_ADD,
    RPN_OP_SUB,
    RPN_OP_MUL,
    RPN_OP_DIV
} rpn_op;

/* Which variant a token is. */
typedef enum rpn_token_kind {
    RPN_TOKEN_NUM,
    RPN_TOKEN_OP
} rpn_token_kind;

/* One token of an expression: a number or an operator (Rust's enum Token). */
typedef struct rpn_token {
    rpn_token_kind kind;
    union {
        double num;
        rpn_op op;
    } as;
} rpn_token;

/* What rpn_tokenize found (Rust's Result<_, LexError>). */
typedef enum rpn_lex_status {
    RPN_LEX_OK = 0,
    RPN_LEX_BAD_CHAR,   /* neither part of a number nor an operator */
    RPN_LEX_BAD_NUMBER, /* a number that doesn't parse, such as 1.2.3 */
    RPN_LEX_NO_MEMORY
} rpn_lex_status;

/* Where tokenizing stopped: the byte offset, and for RPN_LEX_BAD_CHAR the character's code
 * point (Rust's LexError fields). */
typedef struct rpn_lex_error {
    size_t at;
    unsigned long ch;
} rpn_lex_error;

/* The tokens of input[0..len), separated by whitespace: *tokens (allocated, freed with
 * rpn_tokens_free; NULL when there are none) and their *count. Unless RPN_LEX_OK, nothing is
 * allocated and *err says where it stopped. */
rpn_lex_status rpn_tokenize(const char *input, size_t len, rpn_token **tokens, size_t *count,
                            rpn_lex_error *err);

void rpn_tokens_free(rpn_token *tokens);

/* The error's message, as Rust's Display wrote it ("unexpected 'x' at 2"), into buf
 * (NUL-terminated, cut to size). Returns the message's length. */
size_t rpn_lex_error_message(rpn_lex_status status, const rpn_lex_error *err, char *buf,
                             size_t size);

#endif /* RPN_LEXER_H */

/* The module rpn::lexer, ported to C: splits an expression into numbers and operators. */
#include "rpn/lexer.h"

#include <stdio.h>
#include <stdlib.h>
#include <string.h>

static int is_digit(char c)
{
    return c >= '0' && c <= '9';
}

static int is_space(char c)
{
    return c == ' ' || c == '\t' || c == '\n' || c == '\r' || c == '\f' || c == '\v';
}

/* The code point of the UTF-8 sequence at s[0..n), or U+FFFD when it isn't one. */
static unsigned long decode_utf8(const unsigned char *s, size_t n)
{
    unsigned long cp;
    size_t len, i;
    if (n == 0) {
        return 0xFFFDUL;
    }
    if (s[0] < 0x80) {
        return s[0];
    }
    if ((s[0] & 0xE0) == 0xC0) {
        len = 2;
        cp = s[0] & 0x1F;
    } else if ((s[0] & 0xF0) == 0xE0) {
        len = 3;
        cp = s[0] & 0x0F;
    } else if ((s[0] & 0xF8) == 0xF0) {
        len = 4;
        cp = s[0] & 0x07;
    } else {
        return 0xFFFDUL;
    }
    if (len > n) {
        return 0xFFFDUL;
    }
    for (i = 1; i < len; i++) {
        if ((s[i] & 0xC0) != 0x80) {
            return 0xFFFDUL;
        }
        cp = (cp << 6) | (unsigned long)(s[i] & 0x3F);
    }
    return cp;
}

/* Whether s[0..n), made of digits, dots and a leading '-', is a number Rust's f64 parser
 * takes: at most one dot, and at least one digit. */
static int is_number(const char *s, size_t n)
{
    size_t i, digits = 0, dots = 0;
    for (i = 0; i < n; i++) {
        if (is_digit(s[i])) {
            digits++;
        } else if (s[i] == '.') {
            dots++;
        } else if (!(s[i] == '-' && i == 0)) {
            return 0;
        }
    }
    return digits > 0 && dots <= 1;
}

static int push(rpn_token **tokens, size_t *count, size_t *cap, rpn_token token)
{
    if (*count == *cap) {
        size_t grown = *cap == 0 ? 8 : *cap * 2;
        rpn_token *more = realloc(*tokens, grown * sizeof **tokens);
        if (more == NULL) {
            return 0;
        }
        *tokens = more;
        *cap = grown;
    }
    (*tokens)[(*count)++] = token;
    return 1;
}

static rpn_lex_status fail(rpn_token *tokens, rpn_lex_status status, rpn_lex_error *err,
                           size_t at, unsigned long ch)
{
    free(tokens);
    err->at = at;
    err->ch = ch;
    return status;
}

rpn_lex_status rpn_tokenize(const char *input, size_t len, rpn_token **tokens_out,
                            size_t *count_out, rpn_lex_error *err)
{
    rpn_token *tokens = NULL;
    size_t count = 0, cap = 0, i = 0;
    while (i < len) {
        char c = input[i];
        rpn_token token;
        int op = -1;
        int next_is_digit = i + 1 < len && is_digit(input[i + 1]);
        if (is_space(c)) {
            i++;
            continue;
        }
        switch (c) {
        case '+':
            op = RPN_OP_ADD;
            break;
        case '-':
            op = RPN_OP_SUB;
            break;
        case '*':
            op = RPN_OP_MUL;
            break;
        case '/':
            op = RPN_OP_DIV;
            break;
        default:
            break;
        }
        if (op >= 0 && !(op == RPN_OP_SUB && next_is_digit)) {
            token.kind = RPN_TOKEN_OP;
            token.as.op = (rpn_op)op;
            if (!push(&tokens, &count, &cap, token)) {
                return fail(tokens, RPN_LEX_NO_MEMORY, err, i, 0);
            }
            i++;
            continue;
        }
        if (is_digit(c) || c == '.' || c == '-') {
            size_t start = i;
            char *text;
            i++;
            while (i < len && (is_digit(input[i]) || input[i] == '.')) {
                i++;
            }
            if (!is_number(input + start, i - start)) {
                return fail(tokens, RPN_LEX_BAD_NUMBER, err, start, 0);
            }
            text = malloc(i - start + 1);
            if (text == NULL) {
                return fail(tokens, RPN_LEX_NO_MEMORY, err, start, 0);
            }
            memcpy(text, input + start, i - start);
            text[i - start] = '\0';
            token.kind = RPN_TOKEN_NUM;
            token.as.num = strtod(text, NULL);
            free(text);
            if (!push(&tokens, &count, &cap, token)) {
                return fail(tokens, RPN_LEX_NO_MEMORY, err, start, 0);
            }
            continue;
        }
        return fail(tokens, RPN_LEX_BAD_CHAR, err, i,
                    decode_utf8((const unsigned char *)input + i, len - i));
    }
    *tokens_out = tokens;
    *count_out = count;
    return RPN_LEX_OK;
}

void rpn_tokens_free(rpn_token *tokens)
{
    free(tokens);
}

/* The UTF-8 encoding of cp into out (at least 5 bytes), NUL-terminated. */
static void encode_utf8(unsigned long cp, char *out)
{
    if (cp < 0x80) {
        out[0] = (char)cp;
        out[1] = '\0';
    } else if (cp < 0x800) {
        out[0] = (char)(0xC0 | (cp >> 6));
        out[1] = (char)(0x80 | (cp & 0x3F));
        out[2] = '\0';
    } else if (cp < 0x10000) {
        out[0] = (char)(0xE0 | (cp >> 12));
        out[1] = (char)(0x80 | ((cp >> 6) & 0x3F));
        out[2] = (char)(0x80 | (cp & 0x3F));
        out[3] = '\0';
    } else {
        out[0] = (char)(0xF0 | (cp >> 18));
        out[1] = (char)(0x80 | ((cp >> 12) & 0x3F));
        out[2] = (char)(0x80 | ((cp >> 6) & 0x3F));
        out[3] = (char)(0x80 | (cp & 0x3F));
        out[4] = '\0';
    }
}

size_t rpn_lex_error_message(rpn_lex_status status, const rpn_lex_error *err, char *buf,
                             size_t size)
{
    char ch[5];
    int n;
    switch (status) {
    case RPN_LEX_BAD_CHAR:
        encode_utf8(err->ch, ch);
        n = snprintf(buf, size, "unexpected '%s' at %lu", ch, (unsigned long)err->at);
        break;
    case RPN_LEX_BAD_NUMBER:
        n = snprintf(buf, size, "bad number at %lu", (unsigned long)err->at);
        break;
    case RPN_LEX_NO_MEMORY:
        n = snprintf(buf, size, "out of memory");
        break;
    default:
        n = snprintf(buf, size, "no error");
        break;
    }
    return n < 0 ? 0 : (size_t)n;
}

