//! Splits an expression into numbers and operators. Implemented in C (c/src/lexer.c, declared
//! in c/include/rpn/lexer.h) behind this unchanged API: the façade is the one place with
//! `unsafe` code.
#![allow(unsafe_code)]

use std::fmt;

/// bindgen's view of c/include/rpn/lexer.h (written before each build; don't edit).
#[allow(non_camel_case_types, non_upper_case_globals, non_snake_case, dead_code, clippy::all)]
mod sys;

/// An arithmetic operator.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Op {
    Add,
    Sub,
    Mul,
    Div,
}

/// One token of an expression.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Token {
    Num(f64),
    Op(Op),
}

/// Why an expression couldn't be split.
#[derive(Debug, Clone, PartialEq, Eq)]
pub enum LexError {
    /// A character that is neither part of a number nor an operator, at a byte offset.
    BadChar { ch: char, at: usize },
    /// A number that doesn't parse, such as `1.2.3`.
    BadNumber { at: usize },
}

fn op_from_c(op: sys::rpn_op) -> Op {
    match op {
        sys::rpn_op_RPN_OP_ADD => Op::Add,
        sys::rpn_op_RPN_OP_SUB => Op::Sub,
        sys::rpn_op_RPN_OP_MUL => Op::Mul,
        _ => Op::Div,
    }
}

impl fmt::Display for LexError {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        let (status, err) = match *self {
            LexError::BadChar { ch, at } => (
                sys::rpn_lex_status_RPN_LEX_BAD_CHAR,
                sys::rpn_lex_error { at, ch: u32::from(ch) as _ },
            ),
            LexError::BadNumber { at } => {
                (sys::rpn_lex_status_RPN_LEX_BAD_NUMBER, sys::rpn_lex_error { at, ch: 0 })
            }
        };
        let mut buf = [0u8; 64];
        // SAFETY: `err` is a valid error, and `buf` has room for `buf.len()` bytes.
        let n = unsafe {
            sys::rpn_lex_error_message(status, &err, buf.as_mut_ptr().cast(), buf.len())
        };
        f.write_str(&String::from_utf8_lossy(&buf[..n.min(buf.len() - 1)]))
    }
}

/// The tokens of `input`, separated by whitespace.
pub fn tokenize(input: &str) -> Result<Vec<Token>, LexError> {
    let mut tokens: *mut sys::rpn_token = std::ptr::null_mut();
    let mut count = 0;
    let mut err = sys::rpn_lex_error { at: 0, ch: 0 };
    // SAFETY: `input` is valid for `input.len()` bytes, the out-pointers for one write each.
    let status = unsafe {
        sys::rpn_tokenize(input.as_ptr().cast(), input.len(), &mut tokens, &mut count, &mut err)
    };
    match status {
        sys::rpn_lex_status_RPN_LEX_OK => {}
        sys::rpn_lex_status_RPN_LEX_BAD_CHAR => {
            let ch = char::from_u32(err.ch as u32).unwrap_or(char::REPLACEMENT_CHARACTER);
            return Err(LexError::BadChar { ch, at: err.at });
        }
        sys::rpn_lex_status_RPN_LEX_BAD_NUMBER => return Err(LexError::BadNumber { at: err.at }),
        _ => std::alloc::handle_alloc_error(std::alloc::Layout::new::<sys::rpn_token>()),
    }
    if tokens.is_null() {
        return Ok(Vec::new());
    }
    // SAFETY: the C returned `count` initialized tokens at `tokens`, which this function owns.
    let found = unsafe { std::slice::from_raw_parts(tokens, count) }
        .iter()
        .map(|t| match t.kind {
            // SAFETY: the kind says which field of the union the C wrote.
            sys::rpn_token_kind_RPN_TOKEN_NUM => Token::Num(unsafe { t.as_.num }),
            _ => Token::Op(op_from_c(unsafe { t.as_.op })),
        })
        .collect();
    // SAFETY: `tokens` came from rpn_tokenize, and nothing uses it after this.
    unsafe { sys::rpn_tokens_free(tokens) };
    Ok(found)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn numbers_and_operators() {
        let tokens = tokenize("3 4.5 + -2 *").unwrap();
        assert_eq!(
            tokens,
            vec![
                Token::Num(3.0),
                Token::Num(4.5),
                Token::Op(Op::Add),
                Token::Num(-2.0),
                Token::Op(Op::Mul),
            ]
        );
    }

    #[test]
    fn a_minus_alone_is_an_operator() {
        assert_eq!(tokenize("5 1 -").unwrap()[2], Token::Op(Op::Sub));
        assert_eq!(tokenize("").unwrap(), vec![]);
    }

    #[test]
    fn errors_say_where() {
        assert_eq!(tokenize("1 x"), Err(LexError::BadChar { ch: 'x', at: 2 }));
        assert_eq!(tokenize("1.2.3"), Err(LexError::BadNumber { at: 0 }));
        assert_eq!(LexError::BadChar { ch: 'x', at: 2 }.to_string(), "unexpected 'x' at 2");
    }
}

/* rpn/reduce.h - the module rpn::reduce, ported to C (CodeCoreMorph, D-75). */
#ifndef RPN_REDUCE_H
#define RPN_REDUCE_H

#include <stdbool.h>
#include <stddef.h>

/* Reduces a list of numbers to one (Rust's trait Reducer): its name, and a function that
 * writes the reduction of xs[0..n) to *out, or returns false for an empty list where the
 * reduction has no value. */
typedef struct rpn_reducer {
    const char *name;
    bool (*reduce)(const double *xs, size_t n, double *out);
} rpn_reducer;

extern const rpn_reducer rpn_reduce_sum;  /* Sum */
extern const rpn_reducer rpn_reduce_mean; /* Mean */
extern const rpn_reducer rpn_reduce_max;  /* Max */

/* The reducer named name[0..len): sum, mean or max; NULL for another name. */
const rpn_reducer *rpn_reduce_by_name(const char *name, size_t len);

/* Each value of xs[0..n) that keep(x, context) accepts, in order, into out (room for n
 * values). Returns how many it kept (Rust's generic filtered, over a closure). */
size_t rpn_reduce_filtered(const double *xs, size_t n, bool (*keep)(double x, void *context),
                           void *context, double *out);

#endif /* RPN_REDUCE_H */

/* The module rpn::reduce, ported to C: reductions over lists of numbers, chosen by name. */
#include "rpn/reduce.h"

#include <string.h>

/* Rust sums floats from -0.0, so an empty sum is -0.0, as is a sum of -0.0s. */
static double total(const double *xs, size_t n)
{
    double sum = -0.0;
    size_t i;
    for (i = 0; i < n; i++) {
        sum += xs[i];
    }
    return sum;
}

static bool sum(const double *xs, size_t n, double *out)
{
    *out = total(xs, n);
    return true;
}

static bool mean(const double *xs, size_t n, double *out)
{
    if (n == 0) {
        return false;
    }
    *out = total(xs, n) / (double)n;
    return true;
}

/* As Rust's fold: a value replaces the best so far unless the best is >= it, so a NaN never
 * stays best once another value follows it. */
static bool max(const double *xs, size_t n, double *out)
{
    double best;
    size_t i;
    if (n == 0) {
        return false;
    }
    best = xs[0];
    for (i = 1; i < n; i++) {
        if (!(best >= xs[i])) {
            best = xs[i];
        }
    }
    *out = best;
    return true;
}

const rpn_reducer rpn_reduce_sum = {"sum", sum};
const rpn_reducer rpn_reduce_mean = {"mean", mean};
const rpn_reducer rpn_reduce_max = {"max", max};

static bool named(const char *name, size_t len, const char *wanted)
{
    return len == strlen(wanted) && memcmp(name, wanted, len) == 0;
}

const rpn_reducer *rpn_reduce_by_name(const char *name, size_t len)
{
    if (named(name, len, "sum")) {
        return &rpn_reduce_sum;
    }
    if (named(name, len, "mean")) {
        return &rpn_reduce_mean;
    }
    if (named(name, len, "max")) {
        return &rpn_reduce_max;
    }
    return NULL;
}

size_t rpn_reduce_filtered(const double *xs, size_t n, bool (*keep)(double x, void *context),
                           void *context, double *out)
{
    size_t i, kept = 0;
    for (i = 0; i < n; i++) {
        if (keep(xs[i], context)) {
            out[kept++] = xs[i];
        }
    }
    return kept;
}

