//! Reductions over lists of numbers, chosen by name. Implemented in C (c/src/reduce.c,
//! declared in c/include/rpn/reduce.h) behind this unchanged API: the C reducers are structs
//! of a name and a function, and the façade is the one place with `unsafe` code.
#![allow(unsafe_code)]

use std::ffi::{c_void, CStr};

/// bindgen's view of c/include/rpn/reduce.h (written before each build; don't edit).
#[allow(non_camel_case_types, non_upper_case_globals, non_snake_case, dead_code, clippy::all)]
mod sys;

/// Reduces a list of numbers to one.
pub trait Reducer {
    fn name(&self) -> &'static str;
    /// None for an empty list, where the reduction has no value.
    fn reduce(&self, xs: &[f64]) -> Option<f64>;
}

pub struct Sum;
pub struct Mean;
pub struct Max;

fn name_of(reducer: &'static sys::rpn_reducer) -> &'static str {
    // SAFETY: the C reducers' names are static, NUL-terminated ASCII.
    unsafe { CStr::from_ptr(reducer.name) }.to_str().unwrap_or("?")
}

fn reduce_with(reducer: &sys::rpn_reducer, xs: &[f64]) -> Option<f64> {
    let reduce = reducer.reduce.expect("every C reducer has a function");
    let mut out = 0.0;
    // SAFETY: `xs` is valid for `xs.len()` reads, `out` for one write.
    unsafe { reduce(xs.as_ptr(), xs.len(), &mut out) }.then_some(out)
}

impl Reducer for Sum {
    fn name(&self) -> &'static str {
        // SAFETY: the C reducer is an immutable static.
        name_of(unsafe { &sys::rpn_reduce_sum })
    }

    fn reduce(&self, xs: &[f64]) -> Option<f64> {
        // SAFETY: as in name.
        reduce_with(unsafe { &sys::rpn_reduce_sum }, xs)
    }
}

impl Reducer for Mean {
    fn name(&self) -> &'static str {
        // SAFETY: the C reducer is an immutable static.
        name_of(unsafe { &sys::rpn_reduce_mean })
    }

    fn reduce(&self, xs: &[f64]) -> Option<f64> {
        // SAFETY: as in name.
        reduce_with(unsafe { &sys::rpn_reduce_mean }, xs)
    }
}

impl Reducer for Max {
    fn name(&self) -> &'static str {
        // SAFETY: the C reducer is an immutable static.
        name_of(unsafe { &sys::rpn_reduce_max })
    }

    fn reduce(&self, xs: &[f64]) -> Option<f64> {
        // SAFETY: as in name.
        reduce_with(unsafe { &sys::rpn_reduce_max }, xs)
    }
}

/// A reducer the C looked up by name.
struct Found(&'static sys::rpn_reducer);

impl Reducer for Found {
    fn name(&self) -> &'static str {
        name_of(self.0)
    }

    fn reduce(&self, xs: &[f64]) -> Option<f64> {
        reduce_with(self.0, xs)
    }
}

/// The reducer of that name: `sum`, `mean` or `max`.
pub fn by_name(name: &str) -> Option<Box<dyn Reducer>> {
    // SAFETY: `name` is valid for `name.len()` bytes; the C returns NULL or a static reducer.
    let found = unsafe { sys::rpn_reduce_by_name(name.as_ptr().cast(), name.len()).as_ref() };
    found.map(|reducer| Box::new(Found(reducer)) as Box<dyn Reducer>)
}

extern "C" fn keep_with<F: Fn(f64) -> bool>(x: f64, context: *mut c_void) -> bool {
    // SAFETY: `context` is the `&F` that `filtered` passed, alive for the call.
    let keep = unsafe { &*(context as *const F) };
    keep(x)
}

/// Each value of `xs` that `keep` accepts, in order.
pub fn filtered<F>(xs: &[f64], keep: F) -> Vec<f64>
where
    F: Fn(f64) -> bool,
{
    let mut out = vec![0.0; xs.len()];
    // SAFETY: `xs` is valid for `xs.len()` reads and `out` for as many writes; the context is
    // `keep`, which outlives the call and which `keep_with::<F>` reads back as an `&F`.
    let kept = unsafe {
        sys::rpn_reduce_filtered(
            xs.as_ptr(),
            xs.len(),
            Some(keep_with::<F>),
            &keep as *const F as *mut c_void,
            out.as_mut_ptr(),
        )
    };
    out.truncate(kept);
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn reducers_by_name() {
        let xs = [2.0, 8.0, 5.0];
        assert_eq!(by_name("sum").unwrap().reduce(&xs), Some(15.0));
        assert_eq!(by_name("mean").unwrap().reduce(&xs), Some(5.0));
        assert_eq!(by_name("max").unwrap().reduce(&xs), Some(8.0));
        assert_eq!(by_name("max").unwrap().name(), "max");
        assert!(by_name("median").is_none());
    }

    #[test]
    fn empty_lists() {
        assert_eq!(Sum.reduce(&[]), Some(0.0));
        assert_eq!(Mean.reduce(&[]), None);
        assert_eq!(Max.reduce(&[]), None);
    }

    #[test]
    fn filtering_with_a_closure() {
        let limit = 4.0;
        assert_eq!(filtered(&[1.0, 5.0, 3.0, 9.0], |x| x < limit), vec![1.0, 3.0]);
    }
}

/* rpn/stack.h - the module rpn::stack, ported to C (CodeCoreMorph, D-75). */
#ifndef RPN_STACK_H
#define RPN_STACK_H

#include <stdbool.h>
#include <stddef.h>

/* A last-in, first-out stack of values of one size, the newest on top (Rust's generic
 * Stack<T>: elements are copied in and out as bytes, as qsort takes them). */
typedef struct rpn_stack rpn_stack;

/* An empty stack of elem_size-byte values; NULL when memory runs out. */
rpn_stack *rpn_stack_new(size_t elem_size);
void rpn_stack_free(rpn_stack *s);

/* Copies elem_size bytes from value onto the top; false when memory runs out. */
bool rpn_stack_push(rpn_stack *s, const void *value);
/* The top value, removed, into out; false when the stack is empty. */
bool rpn_stack_pop(rpn_stack *s, void *out);
/* The top value, left in place, into out; false when the stack is empty. */
bool rpn_stack_peek(const rpn_stack *s, void *out);
size_t rpn_stack_len(const rpn_stack *s);
bool rpn_stack_is_empty(const rpn_stack *s);

#endif /* RPN_STACK_H */

/* The module rpn::stack, ported to C: a last-in, first-out stack. */
#include "rpn/stack.h"

#include <stdint.h>
#include <stdlib.h>
#include <string.h>

struct rpn_stack {
    unsigned char *items;
    size_t elem_size;
    size_t len;
    size_t cap;
};

rpn_stack *rpn_stack_new(size_t elem_size)
{
    rpn_stack *s = malloc(sizeof *s);
    if (s == NULL) {
        return NULL;
    }
    s->items = NULL;
    s->elem_size = elem_size;
    s->len = 0;
    s->cap = 0;
    return s;
}

void rpn_stack_free(rpn_stack *s)
{
    if (s != NULL) {
        free(s->items);
        free(s);
    }
}

bool rpn_stack_push(rpn_stack *s, const void *value)
{
    if (s->len == s->cap) {
        size_t cap;
        if (s->cap > SIZE_MAX / 2) {
            return false;
        }
        cap = s->cap == 0 ? 8 : s->cap * 2;
        if (s->elem_size != 0) {
            unsigned char *items;
            if (cap > SIZE_MAX / s->elem_size) {
                return false;
            }
            items = realloc(s->items, cap * s->elem_size);
            if (items == NULL) {
                return false;
            }
            s->items = items;
        }
        s->cap = cap;
    }
    if (s->elem_size != 0) {
        memcpy(s->items + s->len * s->elem_size, value, s->elem_size);
    }
    s->len++;
    return true;
}

bool rpn_stack_pop(rpn_stack *s, void *out)
{
    if (s->len == 0) {
        return false;
    }
    s->len--;
    if (s->elem_size != 0) {
        memcpy(out, s->items + s->len * s->elem_size, s->elem_size);
    }
    return true;
}

bool rpn_stack_peek(const rpn_stack *s, void *out)
{
    if (s->len == 0) {
        return false;
    }
    if (s->elem_size != 0) {
        memcpy(out, s->items + (s->len - 1) * s->elem_size, s->elem_size);
    }
    return true;
}

size_t rpn_stack_len(const rpn_stack *s)
{
    return s->len;
}

bool rpn_stack_is_empty(const rpn_stack *s)
{
    return s->len == 0;
}

