//! A last-in, first-out stack. Implemented in C (c/src/stack.c, declared in
//! c/include/rpn/stack.h) behind this unchanged API: the C stack copies each value's bytes, so
//! one C stack serves every `T: Copy`. The façade is the one place with `unsafe` code.
#![allow(unsafe_code)]

use std::fmt;
use std::marker::PhantomData;
use std::mem::{self, MaybeUninit};
use std::ptr::NonNull;

/// bindgen's view of c/include/rpn/stack.h (written before each build; don't edit).
#[allow(non_camel_case_types, non_upper_case_globals, non_snake_case, dead_code, clippy::all)]
mod sys;

/// A stack of values, the newest on top.
pub struct Stack<T> {
    raw: NonNull<sys::rpn_stack>,
    _items: PhantomData<T>,
}

fn out_of_memory() -> ! {
    std::alloc::handle_alloc_error(std::alloc::Layout::new::<sys::rpn_stack>())
}

impl<T: Copy> Stack<T> {
    pub fn new() -> Self {
        // SAFETY: a plain size in; the C returns NULL or a stack this value now owns.
        match NonNull::new(unsafe { sys::rpn_stack_new(mem::size_of::<T>()) }) {
            Some(raw) => Stack { raw, _items: PhantomData },
            None => out_of_memory(),
        }
    }

    pub fn push(&mut self, value: T) {
        // SAFETY: the stack is live and copies size_of::<T>() bytes from `value`.
        let pushed =
            unsafe { sys::rpn_stack_push(self.raw.as_ptr(), (&value as *const T).cast()) };
        if !pushed {
            out_of_memory();
        }
    }

    /// The top value, removed; None when the stack is empty.
    pub fn pop(&mut self) -> Option<T> {
        let mut out = MaybeUninit::<T>::uninit();
        // SAFETY: the stack is live; on true it wrote a whole T, which it copied in as one.
        unsafe { sys::rpn_stack_pop(self.raw.as_ptr(), out.as_mut_ptr().cast()) }
            .then(|| unsafe { out.assume_init() })
    }

    /// The top value, left in place.
    pub fn peek(&self) -> Option<T> {
        let mut out = MaybeUninit::<T>::uninit();
        // SAFETY: as in pop.
        unsafe { sys::rpn_stack_peek(self.raw.as_ptr(), out.as_mut_ptr().cast()) }
            .then(|| unsafe { out.assume_init() })
    }

    pub fn len(&self) -> usize {
        // SAFETY: the stack is live.
        unsafe { sys::rpn_stack_len(self.raw.as_ptr()) }
    }

    pub fn is_empty(&self) -> bool {
        // SAFETY: the stack is live.
        unsafe { sys::rpn_stack_is_empty(self.raw.as_ptr()) }
    }
}

impl<T: Copy> Default for Stack<T> {
    fn default() -> Self {
        Self::new()
    }
}

impl<T> Drop for Stack<T> {
    fn drop(&mut self) {
        // SAFETY: this value owns the stack, and nothing uses it after the drop.
        unsafe { sys::rpn_stack_free(self.raw.as_ptr()) }
    }
}

impl<T> fmt::Debug for Stack<T> {
    fn fmt(&self, f: &mut fmt::Formatter) -> fmt::Result {
        // SAFETY: the stack is live.
        let len = unsafe { sys::rpn_stack_len(self.raw.as_ptr()) };
        f.debug_struct("Stack").field("len", &len).finish()
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn last_in_first_out() {
        let mut s = Stack::new();
        s.push(1.0);
        s.push(2.5);
        assert_eq!(s.len(), 2);
        assert_eq!(s.peek(), Some(2.5));
        assert_eq!(s.pop(), Some(2.5));
        assert_eq!(s.pop(), Some(1.0));
        assert_eq!(s.pop(), None);
        assert!(s.is_empty());
    }
}

/* rpn/eval.h - the module rpn::eval, ported to C (CodeCoreMorph, D-75). */
#ifndef RPN_EVAL_H
#define RPN_EVAL_H

#include <stddef.h>

#include "rpn/lexer.h"

/* Why an expression has no value (Rust's enum EvalError), or RPN_EVAL_OK. */
typedef enum rpn_eval_status {
    RPN_EVAL_OK = 0,
    RPN_EVAL_LEX,              /* the expression doesn't split: rpn_eval_error.lex says why */
    RPN_EVAL_UNDERFLOW,        /* an operator with fewer than two values before it */
    RPN_EVAL_DIVIDE_BY_ZERO,
    RPN_EVAL_LEFTOVER,         /* values left over: rpn_eval_error.leftover of them */
    RPN_EVAL_EMPTY,
    RPN_EVAL_NO_MEMORY
} rpn_eval_status;

/* The details of an error: the lexer's, or how many values were left over. */
typedef struct rpn_eval_error {
    rpn_lex_status lex;
    rpn_lex_error lex_error;
    size_t leftover;
} rpn_eval_error;

/* The value of tokens[0..n), in reverse Polish notation, into *out. */
rpn_eval_status rpn_eval(const rpn_token *tokens, size_t n, double *out, rpn_eval_error *err);

/* The value of an expression written out, input[0..len), such as "3 4 + 2 *". */
rpn_eval_status rpn_eval_str(const char *input, size_t len, double *out, rpn_eval_error *err);

/* The error's message, as Rust's Display wrote it ("division by zero"), into buf
 * (NUL-terminated, cut to size). Returns the message's length. */
size_t rpn_eval_error_message(rpn_eval_status status, const rpn_eval_error *err, char *buf,
                              size_t size);

#endif /* RPN_EVAL_H */

/* The module rpn::eval, ported to C: evaluates reverse Polish notation. */
#include "rpn/eval.h"

#include <stdio.h>

#include "rpn/stack.h"

static rpn_eval_status apply(rpn_op op, double a, double b, double *out)
{
    switch (op) {
    case RPN_OP_ADD:
        *out = a + b;
        return RPN_EVAL_OK;
    case RPN_OP_SUB:
        *out = a - b;
        return RPN_EVAL_OK;
    case RPN_OP_MUL:
        *out = a * b;
        return RPN_EVAL_OK;
    case RPN_OP_DIV:
        if (b == 0.0) {
            return RPN_EVAL_DIVIDE_BY_ZERO;
        }
        *out = a / b;
        return RPN_EVAL_OK;
    }
    return RPN_EVAL_OK;
}

rpn_eval_status rpn_eval(const rpn_token *tokens, size_t n, double *out, rpn_eval_error *err)
{
    rpn_eval_status status = RPN_EVAL_OK;
    rpn_stack *stack = rpn_stack_new(sizeof(double));
    size_t i, len;
    if (stack == NULL) {
        return RPN_EVAL_NO_MEMORY;
    }
    for (i = 0; i < n && status == RPN_EVAL_OK; i++) {
        double a, b, value;
        if (tokens[i].kind == RPN_TOKEN_NUM) {
            if (!rpn_stack_push(stack, &tokens[i].as.num)) {
                status = RPN_EVAL_NO_MEMORY;
            }
            continue;
        }
        if (!rpn_stack_pop(stack, &b) || !rpn_stack_pop(stack, &a)) {
            status = RPN_EVAL_UNDERFLOW;
            continue;
        }
        status = apply(tokens[i].as.op, a, b, &value);
        if (status == RPN_EVAL_OK && !rpn_stack_push(stack, &value)) {
            status = RPN_EVAL_NO_MEMORY;
        }
    }
    if (status == RPN_EVAL_OK) {
        len = rpn_stack_len(stack);
        if (len == 0) {
            status = RPN_EVAL_EMPTY;
        } else if (len == 1) {
            (void)rpn_stack_pop(stack, out);
        } else {
            err->leftover = len - 1;
            status = RPN_EVAL_LEFTOVER;
        }
    }
    rpn_stack_free(stack);
    return status;
}

rpn_eval_status rpn_eval_str(const char *input, size_t len, double *out, rpn_eval_error *err)
{
    rpn_token *tokens = NULL;
    size_t count = 0;
    rpn_eval_status status;
    rpn_lex_status lexed = rpn_tokenize(input, len, &tokens, &count, &err->lex_error);
    if (lexed != RPN_LEX_OK) {
        err->lex = lexed;
        return lexed == RPN_LEX_NO_MEMORY ? RPN_EVAL_NO_MEMORY : RPN_EVAL_LEX;
    }
    status = rpn_eval(tokens, count, out, err);
    rpn_tokens_free(tokens);
    return status;
}

size_t rpn_eval_error_message(rpn_eval_status status, const rpn_eval_error *err, char *buf,
                              size_t size)
{
    int n;
    switch (status) {
    case RPN_EVAL_LEX:
        return rpn_lex_error_message(err->lex, &err->lex_error, buf, size);
    case RPN_EVAL_UNDERFLOW:
        n = snprintf(buf, size, "not enough values");
        break;
    case RPN_EVAL_DIVIDE_BY_ZERO:
        n = snprintf(buf, size, "division by zero");
        break;
    case RPN_EVAL_LEFTOVER:
        n = snprintf(buf, size, "%lu values left over", (unsigned long)err->leftover);
        break;
    case RPN_EVAL_EMPTY:
        n = snprintf(buf, size, "nothing to evaluate");
        break;
    case RPN_EVAL_NO_MEMORY:
        n = snprintf(buf, size, "out of memory");
        break;
    default:
        n = snprintf(buf, size, "no error");
        break;
    }
    return n < 0 ? 0 : (size_t)n;
}

