use std::fmt;

use crate::lexer::{LexError, Op, Token};

/// bindgen's view of c/include/rpn/eval.h (written before each build; don't edit).
#[allow(non_camel_case_types, non_upper_case_globals, non_snake_case, dead_code, clippy::all)]
