/* The program rpn, ported to C: evaluates each argument as a reverse Polish expression, or
 * reduces numbers:
 *
 *     rpn '3 4 +' '2 3 *'        prints 7 and 6, one per line
 *     rpn --reduce mean 1 2 6    prints 3
 *
 * Exits with 1 when an expression has no value, 2 on a usage error. */
#include "rpn/rpn.h"

#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#include "rpn/eval.h"
#include "rpn/reduce.h"

static int usage(void)
{
    fputs("usage: rpn EXPRESSION...\n       rpn --reduce sum|mean|max NUMBER...\n", stderr);
    return 2;
}

static int lower(char c)
{
    return c >= 'A' && c <= 'Z' ? c - 'A' + 'a' : c;
}

static int same_word(const char *s, const char *word)
{
    while (*s != '\0' && *word != '\0' && lower(*s) == *word) {
        s++;
        word++;
    }
    return *s == '\0' && *word == '\0';
}

static int is_digit(char c)
{
    return c >= '0' && c <= '9';
}

/* Whether s is a number Rust's f64 parser takes: a sign, then inf, infinity or nan (any
 * case), or digits with at most one dot and at least one digit, then an exponent. */
static int rust_float(const char *s)
{
    size_t digits = 0;
    if (*s == '+' || *s == '-') {
        s++;
    }
    if (same_word(s, "inf") || same_word(s, "infinity") || same_word(s, "nan")) {
        return 1;
    }
    while (is_digit(*s)) {
        s++;
        digits++;
    }
    if (*s == '.') {
        s++;
        while (is_digit(*s)) {
            s++;
            digits++;
        }
    }
    if (digits == 0) {
        return 0;
    }
    if (*s == 'e' || *s == 'E') {
        s++;
        if (*s == '+' || *s == '-') {
            s++;
        }
        if (!is_digit(*s)) {
            return 0;
        }
        while (is_digit(*s)) {
            s++;
        }
    }
    return *s == '\0';
}

/* x as Rust's Display writes an f64: the fewest digits that read back as x, never with an
 * exponent ("0.30000000000000004", "1e20" as 1 and twenty zeros, "-0", "NaN", "inf"). */
static void print_f64(double x)
{
    char sci[40], digits[24], *mantissa, *e;
    int precision, exponent, count = 0, i;
    if (isnan(x)) {
        puts("NaN");
        return;
    }
    if (isinf(x)) {
        puts(x < 0 ? "-inf" : "inf");
        return;
    }
    for (precision = 0; precision < 17; precision++) {
        snprintf(sci, sizeof sci, "%.*e", precision, x);
        if (strtod(sci, NULL) == x) {
            break;
        }
    }
    mantissa = sci;
    if (*mantissa == '-') {
        putchar('-');
        mantissa++;
    }
    e = strchr(mantissa, 'e');
    exponent = e != NULL ? atoi(e + 1) : 0;
    for (i = 0; mantissa + i != e && mantissa[i] != '\0'; i++) {
        if (is_digit(mantissa[i]) && count < (int)sizeof digits - 1) {
            digits[count++] = mantissa[i];
        }
    }
    digits[count] = '\0';
    if (exponent >= 0) {
        for (i = 0; i <= exponent || i < count; i++) {
            if (i == exponent + 1) {
                putchar('.');
            }
            putchar(i < count ? digits[i] : '0');
        }
    } else {
        fputs("0.", stdout);
        for (i = 1; i < -exponent; i++) {
            putchar('0');
        }
        fputs(digits, stdout);
    }
    putchar('\n');
}

static int reduce_numbers(int argc, char **argv)
{
    const rpn_reducer *reducer;
    double *xs, value;
    size_t n = 0;
    int i;
    reducer = argc > 2 ? rpn_reduce_by_name(argv[2], strlen(argv[2])) : NULL;
    if (reducer == NULL) {
        return usage();
    }
    xs = malloc(sizeof *xs * (size_t)(argc > 3 ? argc - 3 : 1));
    if (xs == NULL) {
        fputs("rpn: out of memory\n", stderr);
        return 1;
    }
    for (i = 3; i < argc; i++) {
        if (!rust_float(argv[i])) {
            free(xs);
            return usage();
        }
        xs[n++] = strtod(argv[i], NULL);
    }
    if (!reducer->reduce(xs, n, &value)) {
        free(xs);
        fprintf(stderr, "rpn: %s of no numbers\n", reducer->name);
        return 1;
    }
    free(xs);
    print_f64(value);
    return 0;
}

int rpn_rpn_main(int argc, char **argv)
{
    int status = 0, i;
    if (argc < 2) {
        return usage();
    }
    if (strcmp(argv[1], "--reduce") == 0) {
        status = reduce_numbers(argc, argv);
        fflush(stdout);
        return status;
    }
    for (i = 1; i < argc; i++) {
        double value;
        rpn_eval_error err;
        char message[128];
        rpn_eval_status result = rpn_eval_str(argv[i], strlen(argv[i]), &value, &err);
        if (result == RPN_EVAL_OK) {
            print_f64(value);
        } else {
            (void)rpn_eval_error_message(result, &err, message, sizeof message);
            fprintf(stderr, "rpn: %s: %s\n", argv[i], message);
            status = 1;
        }
    }
    fflush(stdout);
    return status;
}

