use std::ffi::{c_void, CStr};

/// bindgen's view of c/include/rpn/reduce.h (written before each build; don't edit).
#[allow(non_camel_case_types, non_upper_case_globals, non_snake_case, dead_code, clippy::all)]
mod sys;

/// Reduces a list of numbers to one.
pub trait Reducer {
    fn name(&self) -> &'static str;
    /// None for an empty list, where the reduction has no value.
    fn reduce(&self, xs: &[f64]) -> Option<f64>;
}

pub struct Sum;
pub struct Mean;
pub struct Max;

fn name_of(reducer: &'static sys::rpn_reducer) -> &'static str {
    // SAFETY: the C reducers' names are static, NUL-terminated ASCII.
    unsafe { CStr::from_ptr(reducer.name) }.to_str().unwrap_or("?")
}

fn reduce_with(reducer: &sys::rpn_reducer, xs: &[f64]) -> Option<f64> {
    let reduce = reducer.reduce.expect("every C reducer has a function");
    let mut out = 0.0;
    // SAFETY: `xs` is valid for `xs.len()` reads, `out` for one write.
    unsafe { reduce(xs.as_ptr(), xs.len(), &mut out) }.then_some(out)
}

impl Reducer for Sum {
    fn name(&self) -> &'static str {
        // SAFETY: the C reducer is an immutable static.
        name_of(unsafe { &sys::rpn_reduce_sum })
    }

    fn reduce(&self, xs: &[f64]) -> Option<f64> {
        // SAFETY: as in name.
        reduce_with(unsafe { &sys::rpn_reduce_sum }, xs)
    }
}

impl Reducer for Mean {
    fn name(&self) -> &'static str {
        // SAFETY: the C reducer is an immutable static.
        name_of(unsafe { &sys::rpn_reduce_mean })
    }

    fn reduce(&self, xs: &[f64]) -> Option<f64> {
        // SAFETY: as in name.
        reduce_with(unsafe { &sys::rpn_reduce_mean }, xs)
    }
}

impl Reducer for Max {
    fn name(&self) -> &'static str {
        // SAFETY: the C reducer is an immutable static.
        name_of(unsafe { &sys::rpn_reduce_max })
    }

    fn reduce(&self, xs: &[f64]) -> Option<f64> {
        // SAFETY: as in name.
        reduce_with(unsafe { &sys::rpn_reduce_max }, xs)
    }
}

/// A reducer the C looked up by name.
struct Found(&'static sys::rpn_reducer);

impl Reducer for Found {
    fn name(&self) -> &'static str {
        name_of(self.0)
    }

    fn reduce(&self, xs: &[f64]) -> Option<f64> {
        reduce_with(self.0, xs)
    }
}

/// The reducer of that name: `sum`, `mean` or `max`.
pub fn by_name(name: &str) -> Option<Box<dyn Reducer>> {
    // SAFETY: `name` is valid for `name.len()` bytes; the C returns NULL or a static reducer.
    let found = unsafe { sys::rpn_reduce_by_name(name.as_ptr().cast(), name.len()).as_ref() };
    found.map(|reducer| Box::new(Found(reducer)) as Box<dyn Reducer>)
}

extern "C" fn keep_with<F: Fn(f64) -> bool>(x: f64, context: *mut c_void) -> bool {
    // SAFETY: `context` is the `&F` that `filtered` passed, alive for the call.
    let keep = unsafe { &*(context as *const F) };
    keep(x)
}

/// Each value of `xs` that `keep` accepts, in order.
pub fn filtered<F>(xs: &[f64], keep: F) -> Vec<f64>
where
    F: Fn(f64) -> bool,
{
    let mut out = vec![0.0; xs.len()];
    // SAFETY: `xs` is valid for `xs.len()` reads and `out` for as many writes; the context is
    // `keep`, which outlives the call and which `keep_with::<F>` reads back as an `&F`.
    let kept = unsafe {
        sys::rpn_reduce_filtered(
            xs.as_ptr(),
            xs.len(),
            Some(keep_with::<F>),
            &keep as *const F as *mut c_void,
            out.as_mut_ptr(),
        )
    };
    out.truncate(kept);
    out
}

