#include "codecoremorph_tap.h"

#include "rpn/stack.h"

static void last_in_first_out(void)
{
    rpn_stack *s = rpn_stack_new(sizeof(double));
    double one = 1.0, two = 2.5, out = 0.0;
    CCM_CHECK(s != NULL);
    if (s == NULL) {
        return;
    }
    CCM_CHECK(rpn_stack_push(s, &one));
    CCM_CHECK(rpn_stack_push(s, &two));
    CCM_CHECK_UINT(rpn_stack_len(s), 2);
    CCM_CHECK(rpn_stack_peek(s, &out));
    CCM_CHECK_NEAR(out, 2.5, 0.0);
    CCM_CHECK(rpn_stack_pop(s, &out));
    CCM_CHECK_NEAR(out, 2.5, 0.0);
    CCM_CHECK(rpn_stack_pop(s, &out));
    CCM_CHECK_NEAR(out, 1.0, 0.0);
    CCM_CHECK(!rpn_stack_pop(s, &out));
    CCM_CHECK(rpn_stack_is_empty(s));
    rpn_stack_free(s);
}

int main(int argc, char **argv)
{
    CCM_SELECT(argc, argv);
    CCM_RUN(last_in_first_out);
    return ccm_done();
}

