/* The tests of tests/cli.rs, translated from Rust (CodeCoreMorph, D-75): the rpn program, run
 * as a user would. CMake builds it beside the tests' directory (c/rpn), which this finds from
 * the test program's own path. POSIX: popen and the shell's redirections. */
#define _POSIX_C_SOURCE 200809L

#include "codecoremorph_tap.h"

#include <stdlib.h>
#include <string.h>
#include <sys/wait.h>

static char program[1024];

struct run {
    char out[256];
    char err[256];
    int status;
};

static void slurp(FILE *f, char *buf, size_t size)
{
    size_t n = f != NULL ? fread(buf, 1, size - 1, f) : 0;
    buf[n] = '\0';
}

/* Runs rpn with args, already quoted for the shell. */
static struct run rpn(const char *args)
{
    struct run r;
    char command[2048], errfile[] = "/tmp/rpn-test-err-XXXXXX";
    FILE *out, *err;
    int fd = mkstemp(errfile), status;
    memset(&r, 0, sizeof r);
    r.status = -1;
    if (fd < 0) {
        return r;
    }
    snprintf(command, sizeof command, "'%s' %s 2>'%s'", program, args, errfile);
    out = popen(command, "r");
    if (out != NULL) {
        slurp(out, r.out, sizeof r.out);
        status = pclose(out);
        r.status = WIFEXITED(status) ? WEXITSTATUS(status) : -1;
    }
    err = fdopen(fd, "r");
    slurp(err, r.err, sizeof r.err);
    if (err != NULL) {
        fclose(err);
    }
    remove(errfile);
    return r;
}

static void evaluates_each_argument(void)
{
    struct run r = rpn("'3 4 +' '2 3 *' '1 4 /'");
    CCM_CHECK_STR(r.out, "7\n6\n0.25\n");
    CCM_CHECK_STR(r.err, "");
    CCM_CHECK_INT(r.status, 0);
}

static void reports_errors_and_keeps_going(void)
{
    struct run r = rpn("'1 0 /' '2 2 +'");
    CCM_CHECK_STR(r.out, "4\n");
    CCM_CHECK_STR(r.err, "rpn: 1 0 /: division by zero\n");
    CCM_CHECK_INT(r.status, 1);
}

static void reduces_numbers(void)
{
    struct run r = rpn("--reduce mean 1 2 6");
    CCM_CHECK_STR(r.out, "3\n");
    r = rpn("--reduce max -1 -7");
    CCM_CHECK_STR(r.out, "-1\n");
    r = rpn("--reduce median 1");
    CCM_CHECK_INT(r.status, 2);
    r = rpn("--reduce max");
    CCM_CHECK_STR(r.out, "");
    CCM_CHECK_STR(r.err, "rpn: max of no numbers\n");
    CCM_CHECK_INT(r.status, 1);
}

int main(int argc, char **argv)
{
    const char *slash = strrchr(argv[0], '/');
    int dir = slash != NULL ? (int)(slash - argv[0]) : 1;
    snprintf(program, sizeof program, "%.*s/../rpn", dir, slash != NULL ? argv[0] : ".");
    CCM_SELECT(argc, argv);
    CCM_RUN(evaluates_each_argument);
    CCM_RUN(reports_errors_and_keeps_going);
    CCM_RUN(reduces_numbers);
    return ccm_done();
}
